from __future__ import absolute_import
from taf.selenium.sbts.pages.v25r2.configuration.configuration_management import definition_errors


class DefinitionErrorsPage(definition_errors.DefinitionErrorsPage):

    def __init__(self, driver):
        super(DefinitionErrorsPage, self).__init__(driver)
        self._view_panel = DefinitionErrorsPageViewPanel(driver)

    def get_definition_errors(self, timeout=60):
        """
        Get definition errors
        :return: list, list contains dict
        """
        self.open_definition_errors_tab()
        return self._view_panel.get_definition_errors(timeout)


class DefinitionErrorsPageViewPanel(definition_errors.DefinitionErrorsPageViewPanel):

    _DEFINITION_ERRORS_TABLE_XPATH = '//blocks-error-table[@id="def-error-table"]//table[@role="table"]'
    _DEFINITION_ERRORS_TABLE_HEAD_XPATH = '//blocks-error-table[@id="def-error-table"]//table[@role="table"]/thead/tr[1]/th'
    _DEFINITION_ERRORS_TABLE_ROW_XPATH = '//blocks-error-table[@id="def-error-table"]//table[@role="table"]/tbody/tr'
